mapper.select:
select  from batch.replay_operation
where tenant_id = #{tenantId}
order by created_at desc, id desc
limit #{limit}

select id from batch.batch_day_replay_session
where tenant_id = #{tenantId} and replay_operation_id = #{operationId}
order by biz_date, id

mapper.update:
update batch.replay_operation
set approved_by = #{approver}, started_at = coalesce(started_at, #{now}), updated_at = #{now}
where tenant_id = #{tenantId} and id = #{operationId} and status = 'PENDING_APPROVAL'

update batch.replay_operation
set status = #{targetStatus}, in_flight_count = 0, completed_at = #{now}, updated_at = #{now}
where tenant_id = #{tenantId}
  and id = #{operationId}
  and status = 'PENDING_APPROVAL'

update batch.replay_operation
set target_workflow_run_id = #{workflowRunId}, updated_at = #{now}
where tenant_id = #{tenantId}
  and target_request_id = #{requestId}
  and operation_type in ('WORKFLOW_NODE', 'WORKFLOW_RUN')
  and status = 'RUNNING'
  and (target_workflow_run_id is null or target_workflow_run_id = #{workflowRunId})
